})

planParamsSchema = z.object({
  id: z.uuid()
})

discountTypeSchema = z.enum(["percentage", "fixed_amount"], {
  error: "Discount type must be percentage or fixed_amount"
})

applyPromoCodeSchema = z
  .object({
    code: promoCodeSchema,

    planId: z.uuid({
      error: "Invalid plan ID"
    })
  })
  .strict()

createPromoCodeSchema = z
  .object({
    code: promoCodeSchema,

    discountType: discountTypeSchema,

    discountValue: discountValueSchema,

    maxUses: positiveIntegerSchema,

    maxUsesPerUser: positiveIntegerSchema,

    startsAt: z.coerce.date({
      error: "Invalid start date"
    }),

    expiresAt: z.coerce.date({
      error: "Invalid expiration date"
    }),

    isActive: z.boolean().default(true)
  })
  .strict()
  .superRefine((data, ctx) => {
    // Percentage discount cannot exceed 100%.
    if (data.discountType === "percentage" && data.discountValue > 100) {
      ctx.addIssue({
        code: "custom",
        path: ["discountValue"],
        message: "Percentage discount cannot exceed 100"
      });
    }

    // Expiration must be after start.
    if (data.expiresAt <= data.startsAt) {
      ctx.addIssue({
        code: "custom",
        path: ["expiresAt"],
        message: "Expiration date must be after start date"
      });
    }

    // Per-user limit cannot exceed the total limit.
    if (data.maxUsesPerUser > data.maxUses) {
      ctx.addIssue({
        code: "custom",
        path: ["maxUsesPerUser"],
        message: "Max uses per user cannot exceed max uses"
      });
    }
  })

updatePromoCodeSchema = z
  .object({
    code: promoCodeSchema.optional(),

    discountType: discountTypeSchema.optional(),

    discountValue: discountValueSchema.optional(),

    maxUses: positiveIntegerSchema.optional(),

    maxUsesPerUser: positiveIntegerSchema.optional(),

    startsAt: z.coerce
      .date({
        error: "Invalid start date"
      })
      .optional(),

    expiresAt: z.coerce
      .date({
        error: "Invalid expiration date"
      })
      .optional(),

    isActive: z.boolean().optional()
  })
  .strict()
  .refine((data) => Object.keys(data).length > 0, {
    message: "At least one field must be provided"
  })
  .superRefine((data, ctx) => {
    // discountType and discountValue must both be present or both absent
    const hasType = data.discountType !== undefined;
    const hasValue = data.discountValue !== undefined;
    if (hasType !== hasValue) {
      ctx.addIssue({
        code: "custom",
        path: hasType ? ["discountValue"] : ["discountType"],
        message: "discountType and discountValue must be provided together"
      });
    }

    // Validate percentage discounts when both fields are supplied.
    if (
      data.discountType === "percentage" &&
      data.discountValue !== undefined &&
      data.discountValue > 100
    ) {
      ctx.addIssue({
        code: "custom",
        path: ["discountValue"],
        message: "Percentage discount cannot exceed 100"
      });
    }

    // Compare dates only when both are supplied.
    if (
      data.startsAt !== undefined &&
      data.expiresAt !== undefined &&
      data.expiresAt <= data.startsAt
    ) {
      ctx.addIssue({
        code: "custom",
        path: ["expiresAt"],
        message: "Expiration date must be after start date"
      });
    }

    // Compare usage limits only when both are supplied.
    if (
      data.maxUses !== undefined &&
      data.maxUsesPerUser !== undefined &&
      data.maxUsesPerUser > data.maxUses
    ) {
      ctx.addIssue({
        code: "custom",
        path: ["maxUsesPerUser"],
        message: "Max uses per user cannot exceed max uses"
      });
    }
  })

promoCodePlanParamsSchema = z.object({
