  customerId: string;
  priceId: string;
  trialPeriodDays?: number;
}

export interface StripeCheckoutDetails {
  priceId: string;
  customerId?: string;
  customerEmail?: string;
  successUrl: string; // must include {CHECKOUT_SESSION_ID}
  cancelUrl: string;
  trialPeriodDays?: number;
  couponId?: string;
  tenantId: string;
  newPlanId?: string;
}

export interface StripeService {
  createCatalog(payload?: {
    name: string;
    description: string;
  }): Promise<Stripe.Product>;
  createPlan(
    productId: string,
    planDetails: StripePriceDetails
  ): Promise<Stripe.Price>;
  stripeOnBoarding(): Promise<Stripe.Product>;
  createCustomer(details: StripeCustomerDetails): Promise<Stripe.Customer>;
  createSubscription(
    details: StripeSubscriptionDetails
  ): Promise<Stripe.Subscription>;
  createCheckoutSession(
    details: StripeCheckoutDetails
  ): Promise<Stripe.Checkout.Session>;
  createPromoCode(type: string, amount: number, discountAppliedFor?: string, currency?: string): Promise<Stripe.Coupon>;
  retrievePromoCode(couponId: string): Promise<Stripe.Coupon>;
  stripe: Stripe;
  updateSubscription(data: {
    paymentProviderSubscriptionId: string;
    stripeSubscriptionItemId: string;
    paymentProviderPriceId: string;
    action: string;
  }): Promise<Stripe.Subscription>;
  retrieveSubscription(subscriptionId: string): Promise<Stripe.Subscription>;
  updateSubscriptionCancellation(
    subscriptionId: string,
    cancelAtPeriodEnds: boolean,
    deleteImmedietly: boolean
  ): Promise<Stripe.Subscription>;
  deleteCustomerByCustomerId(customerId: string): Promise<boolean>;
  createCustomerPortalSession(
    customerId: string,
    returnUrl: string
  ): Promise<string>;
}

export interface CreateFeatureDTO {
  code: string;
  name: string;
  name_ar: string;
  description?: string | null;
  description_ar?: string | null;
  type: FeatureType;
  unit?: string | null;
  unit_ar?: string | null;
  aggregationType?: AggregationType;
  resetCycle?: ResetCycle;
}

export interface UpdateFeatureDTO {
  name?: string;
  name_ar?: string;
  description?: string | null;
  description_ar?: string | null;
  type?: FeatureType;
  unit?: string | null;
  unit_ar?: string | null;
  aggregationType?: AggregationType;
  resetCycle?: ResetCycle;
}

export interface LinkFeatureDTO {
  plan_id: string;
  feature_id: string;
  limit_value?: number | null;
}

export interface BillingOptionType {
  period: string;
  months: number;
  discountPercent: number;
  stripePriceId?: string;
}

export interface PlanBillingOptionType extends Omit<BillingOptionType, "months"> {
  months?: number;
  intervalUnit?: "day" | "month" | "year";
  intervalCount?: number;
}

export interface PlanFeatureInputDto {
  featureId: string;
  limitValue?: number | null; // null means unlimited
}

export interface CreatePlanDto {
  name: string;
  description?: string;
  price: number;
  currency?: string;
  billingIntervalValue: number;
  billingIntervalUnit: string;
  trialPeriodValue?: number;
  paymentProviderProductId?: string;
  paymentProviderPlanId?: string;
  isActive?: boolean; // Defaults to true
  billingOptions?: BillingOptionType[]; // Dynamic discount tabs
  features?: PlanFeatureInputDto[]; // Linked features and limits
}

export type AuthenticatedUser = JwtPayload & {
  user_id?: string;
  id: string;
  email: string;
  tenant_id?: string;
  /** Canonical role key from TenantUser/SystemRole (for example: owner, admin). */
  roleKey: string;
};

export interface AppRequest extends Request {
  user?: AuthenticatedUser;
  tenant_id?: string;
  tenantUser?: {
    roleKey: string;
    role?: {
      permissions: unknown;
    } | null;
    tenant?: {
      businessType: string | null;
    } | null;
  } | null;
  stripeEvent?: Stripe.Event;
}

export interface Error {
  message: string;
  statusCode: number;
  code: string;
  details?: unknown;
}

export interface SuccessResponse<T> {
  success: true;
  message: string;
  data: T;
}

export interface ErrorResponse {
  success: false;
  error: Error;
}

export type ServiceResult<T> =
  | { success: true; data: T; message?: string }
  | { success: false; code: string; message?: string };

export interface TokenPayload {
  user_id?: string;
  id: string;
  tenant_id?: string;
  email: string;
  roleKey: string;
  sessionId?: string;
  sessionVersion?: number;
}
